contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(
        uint64 _number,
        uint64 _timestamp,
        uint256 _basefee,
        bytes32 _hash,
        uint64 _sequenceNumber,
        bytes32 _batcherHash,
        uint256 _l1FeeOverhead,
        uint256 _l1FeeScalar
    ) public {
        uint64 n0 = c.number(); if (__ESBMC_reverted()) return;
        uint64 t0 = c.timestamp(); if (__ESBMC_reverted()) return;
        uint256 b0 = c.basefee(); if (__ESBMC_reverted()) return;
        bytes32 h0 = c.hash(); if (__ESBMC_reverted()) return;
        uint64 s0 = c.sequenceNumber(); if (__ESBMC_reverted()) return;
        bytes32 bh0 = c.batcherHash(); if (__ESBMC_reverted()) return;
        uint256 o0 = c.l1FeeOverhead(); if (__ESBMC_reverted()) return;
        uint256 sc0 = c.l1FeeScalar(); if (__ESBMC_reverted()) return;
        bool reverted;
        c.setL1BlockValues(_number, _timestamp, _basefee, _hash, _sequenceNumber, _batcherHash, _l1FeeOverhead, _l1FeeScalar); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        assert(
            reverted &&
            c.number() == n0 &&
            c.timestamp() == t0 &&
            c.basefee() == b0 &&
            c.hash() == h0 &&
            c.sequenceNumber() == s0 &&
            c.batcherHash() == bh0 &&
            c.l1FeeOverhead() == o0 &&
            c.l1FeeScalar() == sc0
        );
    }
    receive() external payable {}
}

