        uint64 t0;
        try c.timestamp() returns (uint64 __r) { t0 = __r; } catch { return; }
        uint256 b0;
        try c.basefee() returns (uint256 __r) { b0 = __r; } catch { return; }
        bytes32 h0;
        try c.hash() returns (bytes32 __r) { h0 = __r; } catch { return; }
